package com.mycompany.ecoactionchat.gui;
import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.time.*;import java.time.format.*;import com.mycompany.ecoactionchat.client.ChatClient;
public class ClientView extends JFrame {
 JTextField nick=new JTextField("Student",9),ip=new JTextField("127.0.0.1",11),port=new JTextField("5000",5),msg=new JTextField();JTextArea chat=new JTextArea();DefaultListModel<String> users=new DefaultListModel<>();DefaultTableModel tm,cm;ChatClient client;JLabel status=new JLabel("● Offline");
 public ClientView(){setTitle("Eco Action Chat - Campus Cleanup");setSize(1050,680);setMinimumSize(new Dimension(900,580));setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);
 Color forest=new Color(24,65,52),green=new Color(37,135,91),bg=new Color(241,248,244);JPanel root=new JPanel(new BorderLayout(10,10));root.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));root.setBackground(bg);setContentPane(root);
 JPanel head=new JPanel(new BorderLayout(10,5));head.setBackground(forest);head.setBorder(BorderFactory.createEmptyBorder(15,16,15,16));JPanel tit=new JPanel(new GridLayout(2,1));tit.setOpaque(false);JLabel title=new JLabel("ECO ACTION CHAT");title.setFont(new Font("SansSerif",1,24));title.setForeground(Color.WHITE);JLabel sub=new JLabel("Campus cleanup • Community coordination");sub.setForeground(new Color(220,240,226));tit.add(title);tit.add(sub);head.add(tit,BorderLayout.WEST);
 JPanel con=new JPanel(new FlowLayout(FlowLayout.RIGHT));con.setOpaque(false);for(String s:new String[]{"Nickname","Server IP","Port"}){JLabel l=new JLabel(s);l.setForeground(Color.WHITE);con.add(l);con.add(s.equals("Nickname")?nick:s.equals("Server IP")?ip:port);}JButton connect=new JButton("Connect"),disconnect=new JButton("Disconnect");connect.setBackground(green);connect.setForeground(Color.WHITE);con.add(connect);con.add(disconnect);head.add(con,BorderLayout.CENTER);root.add(head,BorderLayout.NORTH);
 chat.setEditable(false);chat.setLineWrap(true);JPanel cp=new JPanel(new BorderLayout(6,6));cp.add(new JScrollPane(chat));JPanel send=new JPanel(new BorderLayout(6,6));send.add(msg);JButton sb=new JButton("Send");send.add(sb,BorderLayout.EAST);cp.add(send,BorderLayout.SOUTH);
 tm=new DefaultTableModel(new Object[]{"Task","Location","Assigned To","Status","Created By"},0){public boolean isCellEditable(int r,int c){return false;}};JTable taskTable=new JTable(tm);taskTable.setRowHeight(25);JPanel tp=new JPanel(new BorderLayout(6,6));tp.add(new JScrollPane(taskTable));JPanel tb=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton add=new JButton("Add Cleanup Task"),done=new JButton("Mark Selected Done");add.setBackground(green);add.setForeground(Color.WHITE);tb.add(add);tb.add(done);tp.add(tb,BorderLayout.SOUTH);
 cm=new DefaultTableModel(new Object[]{"Team/Name","Bags","Area","Notes","Time"},0){public boolean isCellEditable(int r,int c){return false;}};JPanel rp=new JPanel(new BorderLayout(6,6));rp.add(new JScrollPane(new JTable(cm)));JButton report=new JButton("Report Collection");report.setBackground(green);report.setForeground(Color.WHITE);rp.add(report,BorderLayout.SOUTH);
 JTabbedPane tabs=new JTabbedPane();tabs.addTab("Group Chat",cp);tabs.addTab("Cleanup Task Board",tp);tabs.addTab("Collection Reports",rp);root.add(tabs,BorderLayout.CENTER);JList<String> list=new JList<>(users);list.setBorder(BorderFactory.createTitledBorder("Online Members"));list.setPreferredSize(new Dimension(145,100));root.add(list,BorderLayout.EAST);JPanel foot=new JPanel(new BorderLayout());foot.setBackground(bg);foot.add(status,BorderLayout.WEST);foot.add(new JLabel("LAN application • Shared reports"),BorderLayout.EAST);root.add(foot,BorderLayout.SOUTH);
 connect.addActionListener(e->connect());disconnect.addActionListener(e->disconnect());sb.addActionListener(e->sendChat());msg.addActionListener(e->sendChat());add.addActionListener(e->addTask());done.addActionListener(e->{int r=taskTable.getSelectedRow();if(r>=0&&connected())client.send("DONE|"+tm.getValueAt(r,0)+"|"+tm.getValueAt(r,1)+"|"+tm.getValueAt(r,2)+"|DONE|"+tm.getValueAt(r,4));else JOptionPane.showMessageDialog(this,"Select a task and connect first.");});report.addActionListener(e->report());}
 boolean connected(){return client!=null&&client.isConnected();}void connect(){if(nick.getText().trim().isEmpty()){JOptionPane.showMessageDialog(this,"Nickname required.");return;}int p;try{p=Integer.parseInt(port.getText().trim());}catch(Exception e){JOptionPane.showMessageDialog(this,"Port must be numeric.");return;}client=new ChatClient(ip.getText().trim(),p,nick.getText().trim(),this);client.connect();}
 public void onConnected(){SwingUtilities.invokeLater(()->status.setText("● Connected"));}public void onError(String e){SwingUtilities.invokeLater(()->JOptionPane.showMessageDialog(this,"Connection failed: "+e));}
 public void onMessage(String l){SwingUtilities.invokeLater(()->{if(l.startsWith("CHAT|")){String[]p=l.split("\\|",3);if(p.length==3)chat.append("["+time()+"] "+p[1]+": "+p[2]+"\\n");}else if(l.startsWith("USERLIST|")){users.clear();String s=l.substring(9);if(!s.isBlank())for(String u:s.split(","))users.addElement(u);}else if(l.startsWith("TASK|"))task(l.substring(5));else if(l.startsWith("COLLECTION|"))collection(l.substring(11));else if(l.startsWith("INFO|"))chat.append("[System] "+l.substring(5)+"\\n");else if(l.startsWith("ERROR|"))JOptionPane.showMessageDialog(this,l.substring(6));});}
 void sendChat(){String m=msg.getText().trim();if(m.isEmpty())return;if(!connected()){chat.append("[System] Connect first.\\n");return;}if(m.equals("/help"))chat.append("[System] /help, /name <nickname>, /exit\\n");else if(m.startsWith("/name "))client.send("RENAME|"+m.substring(6).trim());else if(m.equals("/exit"))disconnect();else client.send("CHAT|"+m);msg.setText("");}
 void addTask(){if(!connected()){JOptionPane.showMessageDialog(this,"Connect first.");return;}JTextField t=new JTextField(),loc=new JTextField(),ass=new JTextField();Object[] f={"Task:",t,"Location:",loc,"Assigned to:",ass};if(JOptionPane.showConfirmDialog(this,f,"New Cleanup Task",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION&&!t.getText().trim().isEmpty()&&!loc.getText().trim().isEmpty())client.send("TASK|"+clean(t.getText())+"|"+clean(loc.getText())+"|"+clean(ass.getText())+"|OPEN|"+clean(nick.getText()));}
 void report(){if(!connected()){JOptionPane.showMessageDialog(this,"Connect first.");return;}JTextField team=new JTextField(nick.getText()),bags=new JTextField("1"),area=new JTextField(),notes=new JTextField();Object[] f={"Team/Name:",team,"Bags collected:",bags,"Area:",area,"Notes:",notes};if(JOptionPane.showConfirmDialog(this,f,"Collection Report",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){try{int n=Integer.parseInt(bags.getText());if(n<1)throw new Exception();client.send("COLLECTION|"+clean(team.getText())+"|"+n+"|"+clean(area.getText())+"|"+clean(notes.getText())+"|"+time());}catch(Exception e){JOptionPane.showMessageDialog(this,"Enter a positive number of bags.");}}}
 void task(String d){String[]p=d.split("\\|",5);if(p.length==5){for(int i=0;i<tm.getRowCount();i++)if(tm.getValueAt(i,0).equals(p[0])&&tm.getValueAt(i,1).equals(p[1])){for(int c=0;c<5;c++)tm.setValueAt(p[c],i,c);return;}tm.addRow(p);}}
 void collection(String d){String[]p=d.split("\\|",5);if(p.length==5)cm.addRow(p);}String clean(String s){return s.replace("|","/").replace("\\n"," ").trim();}String time(){return LocalTime.now().format(DateTimeFormatter.ofPattern("HH:mm"));}void disconnect(){if(client!=null)client.disconnect();status.setText("● Offline");}
}